package com.ebdf.controller;
import com.ebdf.dao.PortalDAO;import com.google.gson.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet("/api/admin/settings") public class AdminSettingsServlet extends HttpServlet {
 private final PortalDAO dao=new PortalDAO();private final Gson gson=new Gson();private static final Set<String> KEYS=Set.of("platformName","supportEmail","allowRegistration","allowBloodRequests","emergencyAlerts");
 private boolean admin(HttpServletRequest q,HttpServletResponse p)throws IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.setStatus(401);p.getWriter().write("{\"message\":\"Please login first\"}");return false;}if(!"ADMIN".equals(s.getAttribute("userRole"))){p.setStatus(403);return false;}return true;}
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json");p.setCharacterEncoding("UTF-8");if(!admin(q,p))return;try{p.getWriter().write(gson.toJson(dao.settings()));}catch(Exception e){p.setStatus(500);p.getWriter().write("{\"message\":\"Unable to load settings; run the Stage 2 database migration\"}");}}
 protected void doPut(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json");p.setCharacterEncoding("UTF-8");if(!admin(q,p))return;try{JsonObject b=gson.fromJson(q.getReader(),JsonObject.class);if(b==null){p.setStatus(400);p.getWriter().write("{\"message\":\"Invalid settings payload\"}");return;}Map<String,String> m=new LinkedHashMap<>();for(Map.Entry<String,JsonElement> e:b.entrySet()){if(!KEYS.contains(e.getKey())||e.getValue()==null||e.getValue().isJsonNull())continue;String value=e.getValue().getAsString().trim();if(Set.of("allowRegistration","allowBloodRequests","emergencyAlerts").contains(e.getKey())&&!Set.of("true","false").contains(value.toLowerCase(Locale.ROOT)))throw new IllegalArgumentException("Boolean setting must be true or false");if("platformName".equals(e.getKey())&&(value.isEmpty()||value.length()>80))throw new IllegalArgumentException("Platform name must be 1-80 characters");if("supportEmail".equals(e.getKey())&&!value.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new IllegalArgumentException("Enter a valid support email");m.put(e.getKey(),value);}if(m.isEmpty()){p.setStatus(400);p.getWriter().write("{\"message\":\"No valid settings supplied\"}");return;}dao.saveSettings(m);p.getWriter().write("{\"message\":\"Settings saved successfully\"}");}catch(Exception e){getServletContext().log("settings save failed",e);p.setStatus(400);p.getWriter().write("{\"message\":\"Unable to save settings. Check the supplied values.\"}");}}
}
